// spec: .qa/e2e/specs/guided-prayer.md
// seed: tests/seed.user1.spec.ts
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

const counterLocator = (page: Page) => page.getByText(/^\d+ מתוך \d+$/).first();

async function rewindToFirst(page: Page) {
  for (let g = 0; g < 80; g++) {
    const m = (await counterLocator(page).innerText()).match(/(\d+) מתוך (\d+)/)!;
    const cur = Number(m[1]);
    if (cur === 1) return;
    await page.getByRole('button', { name: 'קודם', exact: true }).click();
    await expect(counterLocator(page)).toHaveText(`${cur - 1} מתוך ${m[2]}`);
  }
}

async function checkShare(page: Page, key: string, prayerName: string) {
  const text = `מצטרפים להתפלל ${prayerName} באפליקציית אור הגאולה?`;
  const url = `https://zichui-harabim.expo.app/prayer/${key}`;

  await page.goto(`/prayer/${key}`);
  await expect(counterLocator(page)).toBeVisible({ timeout: 20_000 });
  await rewindToFirst(page);
  await page.evaluate(() => ((window as any).__shares = []));
  const share = page.getByRole('button', { name: 'שיתוף התפילה' });

  // Окно: заголовок, строка, текст, ссылка, кнопки; «ביטול» не отправляет.
  await share.click();
  const dialog = page.getByRole('dialog');
  await expect(dialog).toContainText('שיתוף התפילה');
  await expect(dialog).toContainText('זו ההודעה שתישלח, בלי שום פרט נוסף:');
  await expect(dialog).toContainText(text);
  await expect(dialog).toContainText(url);
  await expect(dialog.getByRole('button', { name: 'ביטול' })).toBeVisible();
  await expect(dialog.getByRole('button', { name: 'המשך לשיתוף' })).toBeVisible();
  await dialog.getByRole('button', { name: 'ביטול' }).click();
  await expect(page.getByRole('dialog')).toHaveCount(0);
  expect(await page.evaluate(() => (window as any).__shares.length)).toBe(0);

  // «המשך לשיתוף» — ровно этот текст и одна ссылка.
  await share.click();
  await page.getByRole('dialog').getByRole('button', { name: 'המשך לשיתוף' }).click();
  await expect.poll(() => page.evaluate(() => (window as any).__shares.length)).toBe(1);
  const payload = await page.evaluate(() => (window as any).__shares[0] as { text?: string; message?: string; url?: string });
  const body = payload.text ?? payload.message ?? '';
  const full = payload.url && !body.includes(payload.url) ? `${body}\n${payload.url}` : body;
  expect(full).toBe(`${text}\n${url}`);
  expect(full.split(url).length - 1).toBe(1);
}

test.describe('Молитва по шагам', () => {
  test('GP-06 Окно «שיתוף התפילה»: текст и ссылка, «ביטול» не отправляет, «המשך לשיתוף» — ровно этот текст #6a86f7df @prod-safe', async ({ page }) => {
    // 1. До перехода: подменить navigator.share (аргумент → window.__shares), canShare = () => true.
    await page.addInitScript(() => {
      const w = window as any;
      w.__shares = [];
      Object.defineProperty(navigator, 'share', {
        configurable: true,
        value: (data: unknown) => {
          w.__shares.push(data);
          return Promise.resolve();
        },
      });
      Object.defineProperty(navigator, 'canShare', { configurable: true, value: () => true });
    });

    // 2. Сохранить localStorage['prayer-progress'].
    await page.goto('/home');
    await expect(page.getByRole('button', { name: 'התחל תפילה' })).toBeVisible({ timeout: 20_000 });
    const saved = await page.evaluate(() => localStorage.getItem('prayer-progress'));
    try {
      // 3–5. /prayer/mincha_sfarad: «קודם» до «1 מתוך 11»; «שיתוף התפילה» → «ביטול»; снова → «המשך לשיתוף».
      await checkShare(page, 'mincha_sfarad', 'מנחה');

      // 6. Повторить для /prayer/arvit_ashkenaz (имя молитвы — из шапки до « (»).
      await page.goto('/prayer/arvit_ashkenaz');
      // Дождаться загрузки молитвы (счётчик «N מתוך M» и непустой h1) — иначе innerText читается до отрисовки шапки.
      const heading = page.getByRole('heading', { level: 1 }).first();
      await expect(counterLocator(page)).toBeVisible({ timeout: 20_000 });
      await expect(heading).not.toHaveText('', { timeout: 20_000 });
      const header = await heading.innerText();
      const name = header.split(' (')[0];
      expect(name.length).toBeGreaterThan(0);
      await checkShare(page, 'arvit_ashkenaz', name);
    } finally {
      // 7. Уборка: вернуть prayer-progress.
      await page.goto('/home');
      await page.evaluate((v) => {
        if (v === null) localStorage.removeItem('prayer-progress');
        else localStorage.setItem('prayer-progress', v);
      }, saved);
    }
  });
});
